function solve(tree) {
  const n = tree.length;
  const present = new Array(n).fill(false);
  if (n > 0 && tree[0] !== -1) {
    present[0] = true;
    for (let i = 1; i < n; i++) {
      present[i] = present[(i - 1) >> 1] && tree[i] !== -1;
    }
  }
  const nodes = [];
  for (let i = 0; i < n; i++) if (present[i]) nodes.push(i);
  const m = nodes.length;
  if (m === 0) return 0;

  const pos = {};
  for (let i = 0; i < m; i++) pos[nodes[i]] = i;
  const parent = new Array(m).fill(-1);
  const kids = [];
  for (let i = 0; i < m; i++) kids.push([]);
  for (let i = 0; i < m; i++) {
    if (nodes[i] !== 0) {
      parent[i] = pos[(nodes[i] - 1) >> 1];
      kids[parent[i]].push(i);
    }
  }

  let best = m;
  const total = 1 << m;
  for (let mask = 0; mask < total; mask++) {
    let cnt = 0;
    for (let t = 0; t < m; t++) if (mask & (1 << t)) cnt++;
    if (cnt >= best) continue;
    let covers = true;
    for (let i = 0; i < m && covers; i++) {
      if (mask & (1 << i)) continue;
      if (parent[i] !== -1 && (mask & (1 << parent[i]))) continue;
      let ok = false;
      for (const c of kids[i]) {
        if (mask & (1 << c)) { ok = true; break; }
      }
      if (!ok) covers = false;
    }
    if (covers) best = cnt;
  }
  return best;
}

function solve(tree) {
  const n = tree.length;
  const present = new Array(n).fill(false);
  if (n > 0 && tree[0] !== -1) {
    present[0] = true;
    for (let i = 1; i < n; i++) {
      present[i] = present[(i - 1) >> 1] && tree[i] !== -1;
    }
  }
  if (n === 0 || !present[0]) return 0;

  let cameras = 0;
  function dfs(i) {
    const l = (2 * i + 1 < n && present[2 * i + 1]) ? dfs(2 * i + 1) : 1;
    const r = (2 * i + 2 < n && present[2 * i + 2]) ? dfs(2 * i + 2) : 1;
    if (l === 0 || r === 0) {
      cameras++;
      return 2;
    }
    if (l === 2 || r === 2) return 1;
    return 0;
  }
  if (dfs(0) === 0) cameras++;
  return cameras;
}
